 const form = document.getElementById('contactForm');
 const fullNameInput = document.getElementById('fullName');
 const emailInput = document.getElementById('email');
 const phoneInput = document.getElementById('phone');
 const successMessage = document.getElementById('successMessage');

 const validators = {
     fullName: (value) => {
         if (!value.trim()) {
             return 'Full name is required';
         }
         if (value.trim().length < 2) {
             return 'Full name must be at least 2 characters';
         }
         return '';
     },
     email: (value) => {
         if (!value.trim()) {
             return 'Email address is required';
         }
         const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         if (!emailRegex.test(value)) {
             return 'Please enter a valid email address';
         }
         return '';
     },
     phone: (value) => {
         if (!value.trim()) {
             return '';
         }
         const phoneRegex = /^[\d\s\-()]+$/;
         if (!phoneRegex.test(value)) {
             return 'Please enter a valid phone number';
         }
         if (value.replace(/\D/g, '').length < 10) {
             return 'Phone number must contain at least 10 digits';
         }
         return '';
     }
 };

 function getErrorElement(fieldName) {
     const input = document.getElementById(fieldName);
     return input.parentElement.querySelector('.error-message');
 }

 function validateField(fieldName) {
     const input = document.getElementById(fieldName);
     const validator = validators[fieldName];
     const errorMessage = validator(input.value);
     const errorElement = getErrorElement(fieldName);

     if (errorMessage) {
         input.classList.add('error');
         errorElement.textContent = errorMessage;
         return false;
     } else {
         input.classList.remove('error');
         errorElement.textContent = '';
         return true;
     }
 }

 function validateForm() {
     const isFullNameValid = validateField('fullName');
     const isEmailValid = validateField('email');
     const isPhoneValid = validateField('phone');

     return isFullNameValid && isEmailValid && isPhoneValid;
 }

 fullNameInput.addEventListener('blur', () => validateField('fullName'));
 emailInput.addEventListener('blur', () => validateField('email'));
 phoneInput.addEventListener('blur', () => validateField('phone'));

 form.addEventListener('submit', (e) => {
     e.preventDefault();

     if (!validateForm()) {
         return;
     }

     const formData = {
         fullName: fullNameInput.value.trim(),
         email: emailInput.value.trim(),
         phone: phoneInput.value.trim()
     };

     console.log('Form submitted:', formData);

     form.style.display = 'none';
     successMessage.style.display = 'block';

     setTimeout(() => {
         form.reset();
         form.style.display = 'block';
         successMessage.style.display = 'none';
         fullNameInput.classList.remove('error');
         emailInput.classList.remove('error');
         phoneInput.classList.remove('error');
         getErrorElement('fullName').textContent = '';
         getErrorElement('email').textContent = '';
         getErrorElement('phone').textContent = '';
     }, 3000);
 });

