    button:hover {
      background: var(--accent-hover);
      transform: translateY(-1px);
    }

    button:focus {
      outline: none;
      box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.16), 0 12px 24px rgba(79, 70, 229, 0.22);
    }

    .form-status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .form-status.is-success {
      padding: 12px 14px;
      border-radius: 12px;
      background: var(--success-bg);
      color: var(--success-text);
    }

    @media (max-width: 640px) {
      .support-card__header,
      form {
        padding-left: 20px;
        padding-right: 20px;
      }
    }
  </style>
</head>
<body>
  <main>
    <section class="support-card" aria-labelledby="support-title">
      <div class="support-card__header">
        <p class="eyebrow">Support</p>
        <h1 id="support-title">Contact our team</h1>
        <p class="support-copy">Send us your details and we will get back to you as soon as possible.</p>
      </div>

      <form id="contactForm" novalidate>
        <div class="form-field">
          <label for="fullName">Full name <span class="required" aria-hidden="true">*</span></label>
          <input id="fullName" name="fullName" type="text" autocomplete="name" required placeholder="Jordan Lee">
          <p class="error-text" id="fullNameError" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="emailAddress">Email address <span class="required" aria-hidden="true">*</span></label>
          <input id="emailAddress" name="emailAddress" type="email" autocomplete="email" required placeholder="jordan@company.com">
          <p class="error-text" id="emailAddressError" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phoneNumber">Phone number</label>
          <input id="phoneNumber" name="phoneNumber" type="tel" autocomplete="tel" placeholder="(555) 123-4567" aria-describedby="phoneHelp phoneError">
          <p class="helper-text" id="phoneHelp">Optional. Use a number like (555) 123-4567 or 555-123-4567.</p>
          <p class="error-text" id="phoneError" aria-live="polite"></p>
        </div>

        <div class="form-actions">
          <button type="submit">Submit request</button>
          <p class="form-status" id="formStatus" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('contactForm');
    const fields = {
      fullName: {
        input: document.getElementById('fullName'),
        error: document.getElementById('fullNameError'),
        validate: value => {
          if (!value.trim()) {
            return 'Full name is required.';
          }
          return '';
        }
      },
      emailAddress: {
        input: document.getElementById('emailAddress'),
        error: document.getElementById('emailAddressError'),
        validate: value => {
          if (!value.trim()) {
            return 'Email address is required.';
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return 'Enter a valid email address.';
          }

          return '';
        }
      },
      phoneNumber: {
        input: document.getElementById('phoneNumber'),
        error: document.getElementById('phoneError'),
        validate: value => {
          const trimmed = value.trim();
          if (!trimmed) {
            return '';
          }

          const phonePattern = /^(\(\d{3}\)\s?\d{3}-\d{4}|\d{3}-\d{3}-\d{4})$/;
          if (!phonePattern.test(trimmed)) {
            return 'Use (555) 123-4567 or 555-123-4567.';
          }

          return '';
        }
      }
    };

    const status = document.getElementById('formStatus');

    function showFieldError(field, message) {
      const fieldContainer = field.input.closest('.form-field');
      const isInvalid = Boolean(message);

      fieldContainer.classList.toggle('is-invalid', isInvalid);
      field.error.textContent = message;
      field.input.setAttribute('aria-invalid', String(isInvalid));
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      showFieldError(field, message);
      return !message;
    }

    Object.values(fields).forEach(field => {
      field.input.addEventListener('blur', () => validateField(field));
      field.input.addEventListener('input', () => {
        if (field.input.getAttribute('aria-invalid') === 'true') {
          validateField(field);
        }
      });
    });

    form.addEventListener('submit', event => {
      event.preventDefault();

      const isValid = Object.values(fields).every(validateField);
      if (!isValid) {
        status.textContent = '';
        status.classList.remove('is-success');
        return;
      }

      status.textContent = 'Thanks — your message has been sent.';
      status.classList.add('is-success');
      form.reset();

      Object.values(fields).forEach(field => showFieldError(field, ''));
    });
  </script>
</body>
</html>
